import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// Local web UI for Agent Evidence Kit. Two build modes share every
// component; only the data adapter differs:
//  - default: talks to the same-origin FastAPI backend (/api/*)
//  - showcase: static sample data generated by the real cores at build
//    time; performs no /api or network calls.
export default defineConfig(({ mode }) => ({
  plugins: [react()],
  server: {
    host: "127.0.0.1",
    port: 5173,
    strictPort: true,
    proxy: {
      "/api": {
        target: "http://127.0.0.1:7411",
        changeOrigin: false,
      },
    },
  },
  build: {
    outDir: mode === "showcase" ? "dist-showcase" : "dist",
    emptyOutDir: true,
    sourcemap: false,
  },
}));
